// Extrae el JSON de la respuesta del agente, aunque venga con markdown o texto extra
const raw = $input.first().json.output || $input.first().json.text || '';

// Busca el primer { y el último } para aislar el objeto JSON
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

if (start === -1 || end === -1) {
  return [{ json: { error: 'No se encontró JSON en la respuesta', raw: raw } }];
}

const jsonStr = raw.slice(start, end + 1);

try {
  const parsed = JSON.parse(jsonStr);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { error: 'JSON inválido', detalle: e.message, raw: raw } }];
}
